import pandas as pd

THRESHOLD_USD = 50000


def should_include(row):
    amount = row["amount_usd"]
    if amount is None or bool(pd.isna(amount)):
        raise StepRefused(
            f"filing {row['filing_id']} reports no lobbying amount, so it cannot be "
            f"placed on either side of the ${THRESHOLD_USD:,} threshold"
        )
    return int(amount) >= THRESHOLD_USD

