import pandas as pd

CATCH_ALL_POLICY_AREA = "Other"


def transform(row):
    policy_area = row["policy_area"]
    targets_bill = row["targets_specific_bill"]
    if policy_area is None or bool(pd.isna(policy_area)):
        raise StepRefused(
            f"filing {row['filing_id']} has no policy area, so whether it needs a "
            f"follow-up read cannot be decided"
        )
    if targets_bill is None or bool(pd.isna(targets_bill)):
        raise StepRefused(
            f"filing {row['filing_id']} has no judgment on whether it names a bill, so "
            f"whether it needs a follow-up read cannot be decided"
        )
    flagged = (not bool(targets_bill)) or str(policy_area) == CATCH_ALL_POLICY_AREA
    return {**row, "needs_followup": bool(flagged)}

import html as _html
import pathlib

import pandas as pd

# Bound to the committed template when the tutorial project is seeded, the way the
# input CSV's path is. The report's markup and stylesheet live in that file.
TEMPLATE_PATH = "[[TEMPLATE_PATH]]"

SECTION_MARKER = "<!--@"
TOKEN_OPEN = "[["
SECTIONS = ("document", "row", "reason", "no_followup")
CATCH_ALL_POLICY_AREA = "Other"
NO_BILL_REASON = "No specific bill named"
CATCH_ALL_REASON = "Catch-all Other policy area"


def transform(df, output_dir):
    sections = _read_template_sections(TEMPLATE_PATH)
    page = _fill(
        sections["document"],
        filing_count=str(len(df)),
        flagged_count=str(int(df["needs_followup"].sum())),
        rows="".join(_render_row(sections, row) for _, row in df.iterrows()),
    )
    out_path = pathlib.Path(output_dir) / "tutorial_triage_report.html"
    out_path.write_text(page, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "filing_count": len(df)}])


def _render_row(sections, row):
    return _fill(
        sections["row"],
        row_class="flagged" if bool(row["needs_followup"]) else "",
        filing_id=_escaped(row["filing_id"]),
        client=_escaped(row["client"]),
        registrant=_escaped(row["registrant"]),
        filing_period=_escaped(row["filing_period"]),
        amount="$" + format(int(row["amount_usd"]), ","),
        policy_area=_escaped(row["policy_area"]),
        primary_ask=_escaped(row["primary_ask"]),
        specific_issues=_escaped(row["specific_issues"]),
        followup=_render_followup(sections, row),
    )


def _render_followup(sections, row):
    """The page has to carry the argument, not just the flag: spend is already in the
    row, so this cell says what Step 3 found missing."""
    if not bool(row["needs_followup"]):
        return sections["no_followup"]
    reasons = []
    if not bool(row["targets_specific_bill"]):
        reasons.append(NO_BILL_REASON)
    if str(row["policy_area"]) == CATCH_ALL_POLICY_AREA:
        reasons.append(CATCH_ALL_REASON)
    if not reasons:
        raise StepRefused(
            f"filing {row['filing_id']} is flagged for follow-up yet names a bill and "
            f"sits outside {CATCH_ALL_POLICY_AREA}, so this report cannot say why it "
            f"was flagged"
        )
    return "".join(_fill(sections["reason"], reason=_escaped(r)) for r in reasons)


def _read_template_sections(path):
    text = pathlib.Path(path).read_text(encoding="utf-8")
    sections = {}
    name = None
    for line in text.splitlines(keepends=True):
        if line.startswith(SECTION_MARKER):
            name = line.strip()[len(SECTION_MARKER):].removesuffix("-->").strip()
            sections[name] = []
        elif name is not None:
            sections[name].append(line)
    missing = [wanted for wanted in SECTIONS if wanted not in sections]
    if missing:
        raise ValueError(f"report template {path} has no {missing} section")
    return {name: "".join(lines) for name, lines in sections.items()}


def _fill(template, **values):
    filled = template
    for name, value in values.items():
        filled = filled.replace(TOKEN_OPEN + name + "]]", value)
    if TOKEN_OPEN in filled:
        raise ValueError(
            f"report template {TEMPLATE_PATH} has a placeholder this step does not fill"
        )
    return filled


def _escaped(value):
    return _html.escape(str(value))
